"""Transactional migration and provisioning of project-owned PostgreSQL schemas."""

from __future__ import annotations

import hashlib
from typing import Any

import psycopg
from psycopg import sql
from psycopg.rows import dict_row

TABLES = (
    "project",
    "agent_def",
    "run",
    "iteration",
    "step",
    "artifact",
    "blackboard",
    "memory",
    "approval",
    "event",
    "run_checkpoint",
    "state_record",
)


def schema_name(base: str, project_id: str) -> str:
    # IDs generated by the application fit PostgreSQL identifiers; hash arbitrary imported IDs.
    suffix = (
        project_id
        if project_id.isascii() and project_id.replace("_", "").isalnum() and len(project_id) <= 40
        else hashlib.sha256(project_id.encode()).hexdigest()[:32]
    )
    return ("proj_" if base == "public" else base[:20] + "_proj_") + suffix


def clone_tables(c: Any, base: str, target: str) -> None:
    c.execute(sql.SQL("CREATE SCHEMA {}").format(sql.Identifier(target)))
    for table in TABLES:
        c.execute(
            sql.SQL("CREATE TABLE {} (LIKE {} INCLUDING ALL)").format(
                sql.Identifier(target, table), sql.Identifier(base, table)
            )
        )
        serials = c.execute(
            """SELECT column_name FROM information_schema.columns
            WHERE table_schema=%s AND table_name=%s AND column_default LIKE 'nextval(%%' """,
            (base, table),
        ).fetchall()
        for row in serials:
            column = row["column_name"]
            seq = table + "_" + column + "_seq"
            c.execute(sql.SQL("CREATE SEQUENCE {}").format(sql.Identifier(target, seq)))
            c.execute(
                sql.SQL("ALTER TABLE {} ALTER COLUMN {} SET DEFAULT nextval({}::regclass)").format(
                    sql.Identifier(target, table), sql.Identifier(column), sql.Literal(f"{target}.{seq}")
                ),
            )
            c.execute(
                sql.SQL("ALTER SEQUENCE {} OWNED BY {}.{}").format(
                    sql.Identifier(target, seq), sql.Identifier(target, table), sql.Identifier(column)
                )
            )
    # LIKE omits foreign keys: recreate them with references resolved within this project.
    c.execute(sql.SQL("SET LOCAL search_path TO {}, {}").format(sql.Identifier(target), sql.Identifier(base)))
    for table in TABLES:
        constraints = c.execute(
            """SELECT conname, pg_get_constraintdef(oid) AS definition FROM pg_constraint
            WHERE conrelid=%s::regclass AND contype='f' """,
            (f"{base}.{table}",),
        ).fetchall()
        for row in constraints:
            definition = row["definition"].replace(f"REFERENCES {base}.", "REFERENCES ")
            c.execute(
                sql.SQL("ALTER TABLE {} ADD CONSTRAINT {} {} DEFERRABLE INITIALLY DEFERRED").format(
                    sql.Identifier(target, table), sql.Identifier(row["conname"]), sql.SQL(definition)
                )
            )
    c.execute(sql.SQL("SET LOCAL search_path TO {}, public").format(sql.Identifier(base)))


def provision(c: Any, base: str, project_id: str) -> str:
    c.execute("SELECT pg_advisory_xact_lock(hashtext(%s))", (base + ":schema:" + project_id,))
    row = c.execute(
        sql.SQL("SELECT schema_name FROM {} WHERE project_id=%s").format(sql.Identifier(base, "project_schema")),
        (project_id,),
    ).fetchone()
    if row:
        return str(row["schema_name"])
    target = schema_name(base, project_id)
    clone_tables(c, base, target)
    for table in ("project", "run", "memory", "agent_def", "blackboard"):
        column = "id" if table == "project" else "project_id"
        c.execute(
            sql.SQL("ALTER TABLE {} ADD CONSTRAINT project_ownership CHECK ({} IS NOT NULL AND {} = {})").format(
                sql.Identifier(target, table), sql.Identifier(column), sql.Identifier(column), sql.Literal(project_id)
            )
        )
    c.execute(
        sql.SQL("INSERT INTO {} VALUES (%s,%s)").format(sql.Identifier(base, "project_schema")), (project_id, target)
    )
    return target


def migrate(database_url: str) -> dict[str, Any]:
    dsn = database_url.replace("postgresql+psycopg://", "postgresql://", 1)
    with psycopg.connect(dsn, row_factory=dict_row) as connection:
        c: Any = connection
        base = c.execute("SELECT current_schema() AS name").fetchone()["name"]
        c.execute("SELECT pg_advisory_xact_lock(712460802)")
        if c.execute("SELECT to_regclass(%s) AS name", (base + ".project_schema",)).fetchone()["name"]:
            return {"already_migrated": True}
        c.execute(
            sql.SQL("CREATE TABLE {} (project_id text PRIMARY KEY, schema_name text UNIQUE NOT NULL)").format(
                sql.Identifier(base, "project_schema")
            )
        )
        c.execute(
            sql.SQL(
                "CREATE TABLE {} (run_id text PRIMARY KEY, project_id text NOT NULL REFERENCES {}(project_id))"
            ).format(sql.Identifier(base, "run_directory"), sql.Identifier(base, "project_schema"))
        )
        for table in TABLES:
            c.execute(sql.SQL("LOCK TABLE {} IN ACCESS EXCLUSIVE MODE").format(sql.Identifier(base, table)))
        archive = "legacy_projects" if base == "public" else base[:20] + "_legacy"
        clone_tables(c, base, archive)
        # Preserve every original row, including global records, as an immutable rollback/export backup.
        for table in TABLES:
            cols = c.execute(
                "SELECT column_name FROM information_schema.columns "
                "WHERE table_schema=%s AND table_name=%s AND is_generated='NEVER' ORDER BY ordinal_position",
                (base, table),
            ).fetchall()
            names = sql.SQL(",").join(sql.Identifier(r["column_name"]) for r in cols)
            c.execute(
                sql.SQL("INSERT INTO {} ({}) SELECT {} FROM {}").format(
                    sql.Identifier(archive, table), names, names, sql.Identifier(base, table)
                )
            )
        projects = c.execute("""SELECT id AS project_id FROM project UNION SELECT project_id FROM run
            UNION SELECT project_id FROM memory WHERE project_id IS NOT NULL
            UNION SELECT project_id FROM blackboard UNION SELECT project_id FROM agent_def WHERE project_id IS NOT NULL
            UNION SELECT data->>'project_id' FROM state_record WHERE data->>'project_id' IS NOT NULL""").fetchall()
        counts: dict[str, dict[str, int]] = {}
        for row in projects:
            pid = row["project_id"]
            target = provision(c, base, pid)
            counts[pid] = {}
            for table in TABLES:
                if table == "project":
                    predicate = "id=%s"
                elif table in {"run", "memory", "agent_def", "blackboard"}:
                    predicate = "project_id=%s"
                elif table == "state_record":
                    predicate = (
                        "data->>'project_id'=%s OR data->>'run_id' IN (SELECT id FROM run WHERE project_id=%s) "
                        "OR key IN (SELECT id FROM run WHERE project_id=%s) "
                        "OR data->>'planning_id' IN (SELECT key FROM state_record "
                        "WHERE kind='planning' AND data->>'project_id'=%s)"
                    )
                else:
                    predicate = "run_id IN (SELECT id FROM run WHERE project_id=%s)"
                params = (pid,) * (4 if table == "state_record" else 1)
                cols = c.execute(
                    "SELECT column_name FROM information_schema.columns "
                    "WHERE table_schema=%s AND table_name=%s AND is_generated='NEVER' ORDER BY ordinal_position",
                    (base, table),
                ).fetchall()
                names = sql.SQL(",").join(sql.Identifier(r["column_name"]) for r in cols)
                c.execute(
                    sql.SQL("INSERT INTO {} ({}) SELECT {} FROM {} WHERE " + predicate).format(
                        sql.Identifier(target, table), names, names, sql.Identifier(base, table)
                    ),
                    params,
                )
                # Compare full row sets as well as counts. Any discrepancy aborts the entire transaction.
                difference = c.execute(
                    sql.SQL(
                        "SELECT count(*) AS n FROM ((SELECT {} FROM {} WHERE "
                        + predicate
                        + ") EXCEPT (SELECT {} FROM {})) AS delta"
                    ).format(names, sql.Identifier(base, table), names, sql.Identifier(target, table)),
                    params,
                ).fetchone()["n"]
                actual = c.execute(
                    sql.SQL("SELECT count(*) AS n FROM {}").format(sql.Identifier(target, table))
                ).fetchone()["n"]
                expected = c.execute(
                    sql.SQL("SELECT count(*) AS n FROM {} WHERE " + predicate).format(sql.Identifier(base, table)),
                    params,
                ).fetchone()["n"]
                if difference or actual != expected:
                    raise RuntimeError(f"migration verification failed: {pid}/{table}")
                serials = c.execute(
                    "SELECT column_name FROM information_schema.columns WHERE table_schema=%s "
                    "AND table_name=%s AND column_default LIKE 'nextval(%%'",
                    (target, table),
                ).fetchall()
                for serial in serials:
                    column = serial["column_name"]
                    c.execute(
                        sql.SQL("SELECT setval(%s::regclass, COALESCE(MAX({}),1), count(*)>0) FROM {}").format(
                            sql.Identifier(column), sql.Identifier(target, table)
                        ),
                        (f"{target}.{table}_{column}_seq",),
                    )
                counts[pid][table] = actual
            c.execute(
                sql.SQL("INSERT INTO {} SELECT id,project_id FROM {}").format(
                    sql.Identifier(base, "run_directory"), sql.Identifier(target, "run")
                )
            )
        # Delete in dependency order; global/shared records alone remain in the base schema.
        for table in (
            "event",
            "approval",
            "artifact",
            "step",
            "iteration",
            "run_checkpoint",
            "run",
            "blackboard",
            "agent_def",
            "project",
        ):
            condition = " WHERE project_id IS NOT NULL" if table == "agent_def" else ""
            c.execute(sql.SQL("DELETE FROM {}" + condition).format(sql.Identifier(base, table)))
        c.execute("DELETE FROM memory WHERE project_id IS NOT NULL")
        for row in projects:
            target = schema_name(base, row["project_id"])
            c.execute(
                sql.SQL("DELETE FROM {} WHERE (kind,key) IN (SELECT kind,key FROM {})").format(
                    sql.Identifier(base, "state_record"), sql.Identifier(target, "state_record")
                )
            )
        c.execute(
            sql.SQL(
                "CREATE FUNCTION {}() RETURNS trigger LANGUAGE plpgsql AS $$ "
                "BEGIN RAISE EXCEPTION 'legacy migration backup is read-only'; END $$"
            ).format(sql.Identifier(archive, "reject_write"))
        )
        for table in TABLES:
            c.execute(
                sql.SQL(
                    "CREATE TRIGGER immutable_backup BEFORE INSERT OR UPDATE OR DELETE OR TRUNCATE ON {} "
                    "FOR EACH STATEMENT EXECUTE FUNCTION {}()"
                ).format(sql.Identifier(archive, table), sql.Identifier(archive, "reject_write"))
            )
        # Old clients must fail loudly rather than repopulating the shared project tables.
        c.execute(
            sql.SQL(
                "CREATE FUNCTION {}() RETURNS trigger LANGUAGE plpgsql AS $$ "
                "BEGIN RAISE EXCEPTION 'project data must use its project schema'; END $$"
            ).format(sql.Identifier(base, "reject_legacy_project_write"))
        )
        for table in (
            "project",
            "run",
            "iteration",
            "step",
            "artifact",
            "blackboard",
            "approval",
            "event",
            "run_checkpoint",
        ):
            c.execute(
                sql.SQL(
                    "CREATE TRIGGER require_project_schema BEFORE INSERT OR UPDATE OR DELETE OR TRUNCATE ON {} "
                    "FOR EACH STATEMENT EXECUTE FUNCTION {}()"
                ).format(sql.Identifier(base, table), sql.Identifier(base, "reject_legacy_project_write"))
            )
        for table in ("memory", "agent_def"):
            c.execute(
                sql.SQL(
                    "CREATE TRIGGER require_project_schema BEFORE INSERT OR UPDATE ON {} "
                    "FOR EACH ROW WHEN (NEW.project_id IS NOT NULL) EXECUTE FUNCTION {}()"
                ).format(sql.Identifier(base, table), sql.Identifier(base, "reject_legacy_project_write"))
            )
        return {"archive": archive, "projects": counts}


def main() -> None:
    """One-time migration entry point; never prints credentials or document contents."""
    import json

    from agentlab.settings import Settings

    url = Settings().database_url
    if not url:
        raise SystemExit("AGENTLAB_DATABASE_URL is required")
    print(json.dumps(migrate(url), indent=2))


if __name__ == "__main__":
    main()
